//generates uniform random position on a sphere
vec3 randpos(vec2 uv) {
    float u = hash(vec2(uv + float(iFrame) + a));
    float v = hash(vec2(uv + u - a));

    float theta = 2.0 * 3.14159265 * u;
    float phi = acos(2.0 * v - 1.0);

    float x = sin(phi) * cos(theta);
    float y = sin(phi) * sin(theta);
    float z = cos(phi);

    return normalize(vec3(x, y, z));
}


//calculates distance the ray must travel until it hits the sphere's edge
float spheredist(vec3 pos, float r){
    vec3 L = pos - rp;
    float tc = dot(L, rd);
    float lenSq = dot(L, L); // equivalent to length(L)*length(L)
    if(tc < 0. || lenSq < tc*tc) {
        return 99999999.; // sphere is behind ray or ray misses sphere
    }
    float dSq = lenSq - tc*tc; // square of distance to center
    if(dSq > r*r) {
        return 99999999.; // ray misses sphere
    }
    float t1Sq = r*r - dSq; // square of distance to intersection
    float t = tc - sqrt(t1Sq);
    float tr = tc + sqrt(t1Sq);
    if(t > 0.) {
        return t;
    } else if(tr > 0.) {
        return tr;
    } else {
        return 99999999.;
    }
}






//main function for calculating color of ray after reflecting, or scattering
void rendersphere(vec3 pos, float r, vec3 colour, float closedist, float blurryp, float block, float gloss, float scatterblur){
    //calculates distance to the sphere defined in the parameters given
    float t = spheredist(pos, r);

    //checks to make sure the ray intersects the sphere and the sphere is the closest to the camera
    if (t >= 0.0 && t == closedist) {
        closedist = -5.;
        //initializes variables. colordp is a variable to change color influence based on the tilt of the surface of the sphere
        float colordp = 1.; 
        rd = normalize(rd);
        rp += rd * t;

        //if the ray gets scattered
        if (random() < blurryp){
            rd = randpos(vec2(random(), random()));
            if(dot(rd, normalize(rp-pos)) < 0.){rd *= -1.;}
            colordp *= dot(normalize(rp - pos), rd);

        //if the ray gets reflected
        }else{
            rd = reflect(rd, normalize(rp - pos));
            //if the ray hits a "polished" layer and doesn't interact with the color of the sphere
            if(random() <= gloss){
            rgb /= colour;
            }

            //calculates noise of the ray based on the blurryness of the sphere
            vec3 temprd = randpos(vec2(random(), random()));
            if(dot(temprd, normalize(rp-pos)) < 0.){temprd *= -1.;}
            rd += temprd * scatterblur * random();
            rd = normalize(rd);
        }

        //gives the sphere a grid texture 
        float tex = 1.;
        if(block == 1.){tex = round(mod(dot(round(rp/3.), vec3(1.,1.,1.)), 2.))/2. + 0.5;}



        //final color calculation
        if(length(colour) < 5.){
            rgb *= colour * colordp * tex;
        }else{
            rgb *= colour;
            i = 999999.;

        }
    }
}


void rendertransparent(vec3 pos, float r, float eta, vec3 color, float closedist) {

    float t = spheredist(pos, r);
    if(t == closedist && t != 99999999.){
        rd = normalize(rd);
        float ref_index;
        vec3 N;
        rp += rd * t;
        N = normalize(rp - pos);
        if(dot(rd, N) > 0.){
            // If the ray is inside the sphere
            ref_index = eta/1.0;
            N = normalize(pos - rp);
        }else if (dot(rd, N) <= 0.){
            // If the ray is outside the sphere
            ref_index = 1.0/eta;
            N = normalize(rp - pos);
        }


        float cos_vector = dot(rd, N);
        float mag = 1./ref_index - 1.;
        if (mag > -1.){
            rd += cos_vector * mag * N; // refracted ray
        }else{
            rd = reflect(rd, N); // total internal reflection
        }
        rd = normalize(rd);
        rp += rd * 0.001;
        rgb*= color;
    }
}







//main image function
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //initializes variables
    uv = fragCoord/iResolution.xy;
    float FOV = 1.0;
    float focal_length = 50.;
    float aperture = 0.;
    float anti_a = 1000.;

    uv -= 0.5;
    uv.x *= iResolution.x/iResolution.y;

    uv *= FOV;
    vec3 average = vec3(0.);

    //begins the loop of firing rays. The upper limit of 'a' determines how many rays will be fired.
    for( a = 1.; a <= 20.; a++){


        rp = vec3(0., 10., 0.);
        rd = vec3(uv.x + (random() - 0.5)/anti_a, uv.y + (random() - 0.5)/anti_a, 1.);
        rd = normalize(rd);

        float randrad = sqrt(random())* aperture;
        float randangle = random() * 2. * 3.14159265358979 ;

        rp += vec3(cos(randangle) * randrad, sin(randangle) * randrad, 0.);
        rd -= vec3(cos(randangle) * randrad, sin(randangle) * randrad, 0.)/focal_length;

        rd = normalize(rd);

        rgb = vec3(.2, .2, .2);
        float closedist = 99999.;
        for(i = 0.; i < 15.; i++){
            float closedist = 99999.;


            //closedist = min(closedist, spheredist(vec3(-300, 400., 100), 70.));
            closedist = min(closedist, spheredist(vec3(0, -999999. - 6.5, 0), 999999.));



            closedist = min(closedist, spheredist(vec3(-400., 100., 200.), 50.));

            closedist = min(closedist, spheredist(vec3(-30., 10., 100.), 15.));
            closedist = min(closedist, spheredist(vec3(-20., 10., 180.), 15.));




            //rendersphere(vec3(-300, 400., 100), 70., vec3(255.,255.,255.)*2., closedist, .9, 0., .2, 0.01);
            rendersphere(vec3(0, -999999. - 6.5, 0), 999999., vec3(1., 1., 1.), closedist, 1., 0., .2, 0.01);

            rendersphere(vec3(-400., 100., 200.), 50., vec3(255.,255.,255.)*5., closedist, 0.99, 0., 1., 0.08);

            rendertransparent(vec3(-30., 10., 100.), 15., 1.8, vec3(.1,1.0,1.0), closedist);
            rendersphere(vec3(-20., 10., 180.), 15., vec3(.5,.1,0.5), closedist, 0.95, 0., 1., 0.15);



            if (closedist == 99999.){
                i = 99999.;
                rgb *= 0.;
            }
        }
        if(a == 1.){
            average = rgb;
        }else{
            average *= (a-1.)/a;
            average += rgb/a;
        }
    }
    //fragColor = vec4(vec3(average), 1.);

    if(iFrame == 0){
        fragColor = vec4(vec3(average), 1.);
    }else{
        fragColor = texture(iChannel0, fragCoord/iResolution.xy);
        fragColor = mix(fragColor, vec4(vec3(average), 1.), 1./max((float(iFrame)-90.), 1.));
    }
}
